def __post_init__(self) -> None:
    X = np.asarray(self.X, dtype=float)
    if X.ndim == 1:
        X = X[:, None]
    if X.ndim != 2:
        raise ValueError(f"X must be 2-dimensional, got shape {X.shape}.")
    n = X.shape[0]
    if not np.isfinite(X).all():
        raise ValueError("X contains NaN or infinite values; impute or drop them first.")
    T = _as_vector(self.T, n, "T")
    Y = _as_vector(self.Y, n, "Y")

    A = sp.csr_array(self.adjacency, dtype=float, copy=True)
    if A.shape != (n, n):
        raise ValueError(f"adjacency must have shape ({n}, {n}), got {A.shape}.")
    A.sum_duplicates()
    if A.diagonal().any():
        warnings.warn("Dropping self-loops from adjacency.", GraphDMLWarning, stacklevel=3)
        A = drop_diagonal(A)
    A.eliminate_zeros()
    A.sort_indices()
    if not self.directed:
        diff = abs(A - A.T)
        if diff.nnz and diff.max() > 1e-10:
            raise ValueError(
                "adjacency is not symmetric. Pass directed=True for directed graphs "
                "(adjacency[i, j] != 0 means j influences i)."
            )

    if self.feature_names is None:
        names = tuple(f"X{k}" for k in range(X.shape[1]))
    else:
        names = tuple(str(s) for s in self.feature_names)
        if len(names) != X.shape[1]:
            raise ValueError(f"Got {len(names)} feature_names for {X.shape[1]} features.")

    ids = np.arange(n) if self.node_ids is None else np.asarray(self.node_ids)
    if ids.shape != (n,):
        raise ValueError(f"node_ids must have shape ({n},), got {ids.shape}.")
    if len(pd.unique(ids)) != n:
        raise ValueError("node_ids must be unique.")

class SumExposure(ExposureMap):
    """``Z_i = sum of in-neighbors' treatments`` (``Z = A T``)."""

    name = "sum"

    def matrix(self, data: GraphData) -> sp.csr_array:
        return data.pattern

    def units(self, binary_treatment: bool) -> str:
        if binary_treatment:
            return "change in Y per additional treated neighbor"
        return "change in Y per unit increase in the sum of neighbors' treatments"


class MeanExposure(ExposureMap):
    """``Z_i = average of in-neighbors' treatments`` (0 for nodes without neighbors)."""

    name = "mean"

    def matrix(self, data: GraphData) -> sp.csr_array:
        return row_normalize(data.pattern)

    def units(self, binary_treatment: bool) -> str:
        if binary_treatment:
            return "change in Y going from 0% to 100% of neighbors treated"
        return "change in Y per unit increase in neighbors' average treatment"


class WeightedExposure(ExposureMap):
    """``Z_i = sum_j w_ij T_j`` using adjacency weights, optionally row-normalised."""

    def __init__(self, normalize: bool = False) -> None:
        self.normalize = normalize

    @property
    def name(self) -> str:  # type: ignore[override]
        return "weighted_mean" if self.normalize else "weighted"

    def matrix(self, data: GraphData) -> sp.csr_array:
        W = data.adjacency
        return row_normalize(W) if self.normalize else W

    def units(self, binary_treatment: bool) -> str:
        return "change in Y per unit of weighted neighbor treatment"

    def __repr__(self) -> str:
        return f"WeightedExposure(normalize={self.normalize})"


class TwoHopExposure(ExposureMap):
    """Treatments of nodes at distance exactly two (summed or averaged).

    Used by :func:`graphdml.two_hop_test` to check the 1-hop interference assumption.
    """

    def __init__(self, normalize: str = "sum") -> None:
        if normalize not in ("sum", "mean"):
            raise ValueError("normalize must be 'sum' or 'mean'.")
        self.normalize = normalize

    @property
    def name(self) -> str:  # type: ignore[override]
        return f"two_hop_{self.normalize}"

    def matrix(self, data: GraphData) -> sp.csr_array:
        P2 = two_hop_pattern(data.pattern)
        return row_normalize(P2) if self.normalize == "mean" else P2

def _population(self, n: int) -> np.ndarray:
    """Nodes the estimate is about: ``estimation_nodes`` if given, else all nodes."""
    if self.estimation_nodes is None:
        return np.arange(n)
    nodes = np.asarray(self.estimation_nodes)
    return np.flatnonzero(nodes) if nodes.dtype == bool else np.unique(nodes.astype(int))

def _focal_nodes(self, dep, spec, rng, n) -> np.ndarray:
    candidates = None
    if self.estimation_nodes is not None:
        candidates = np.asarray(self.estimation_nodes)
        if candidates.dtype == bool:
            if candidates.shape != (n,):
                raise ValueError("A boolean estimation_nodes mask needs one entry per node.")
            candidates = np.flatnonzero(candidates)
        candidates = np.unique(candidates.astype(np.int64))
    if spec is None:
        return np.arange(n) if candidates is None else candidates
    if isinstance(spec, str):
        return select_focal_set(dep, spec, rng, candidates=candidates)
    focal = np.unique(np.asarray(spec, dtype=np.int64))
    if focal.size == 0 or focal.min() < 0 or focal.max() >= n:
        raise ValueError("focal_set indices must be node positions in [0, n_nodes).")
    if not is_independent(dep, focal):
        raise ValueError(
            "The given focal nodes have overlapping dependency sets, so their scores are "
            "not independent. Use graphdml.focal.select_focal_set to build a valid set."
        )
    return focal

    def forward(self, x):
        """
        :param x: torch.tensor, batch_size * 1
        :return: the value of each basis given x; batch_size * self.num_of_basis
        """
        x = x.squeeze()
        out = torch.zeros(x.shape[0], self.num_of_basis).cuda()
        for _ in range(self.num_of_basis):
            if _ <= self.degree:
                if _ == 0:
                    out[:, _] = 1.
                else:
                    out[:, _] = x**_
            else:
                if self.degree == 1:
                    out[:, _] = (self.relu(x - self.knots[_ - self.degree]))
                else:
                    out[:, _] = (self.relu(x - self.knots[_ - self.degree - 1])) ** self.degree

        return out # bs, num_of_basis


class TR(nn.Module):
    def __init__(self, degree, knots):
        super(TR, self).__init__()
        self.spb = Truncated_power(degree, knots)
        self.d = self.spb.num_of_basis # num of basis
        self.weight = torch.nn.Parameter(torch.rand(self.d, device='cuda'), requires_grad=True)

    def forward(self, t):
        out = self.spb.forward(t)
        out = torch.matmul(out, self.weight)

